import{_ as e,c as i,o as l,a3 as s}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"Solución de problemas","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/troubleshooting.md","filePath":"es/guide/troubleshooting.md","lastUpdated":1786595765000}'),o={name:"es/guide/troubleshooting.md"};function r(n,a,t,c,p,d){return l(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h1><p>Esta página recopila problemas comunes con ClipboardxAI en macOS y cómo resolverlos.</p><h2 id="la-aplicacion-no-arranca-o-se-cierra-al-iniciar" tabindex="-1">La aplicación no arranca o se cierra al iniciar <a class="header-anchor" href="#la-aplicacion-no-arranca-o-se-cierra-al-iniciar" aria-label="Permalink to &quot;La aplicación no arranca o se cierra al iniciar&quot;">​</a></h2><ol><li>Asegúrese de que su versión de macOS cumple el mínimo (macOS 14 Sonoma+).</li><li>Salga y vuelva a abrir la aplicación.</li><li>Reinicie su Mac.</li><li>Si la descargó desde GitHub Releases, pruebe la última compilación o la notarizada.</li><li>Si los problemas persisten, recopile los registros (abajo) y abra un issue.</li></ol><h2 id="el-historial-del-portapapeles-no-captura-las-copias" tabindex="-1">El historial del portapapeles no captura las copias <a class="header-anchor" href="#el-historial-del-portapapeles-no-captura-las-copias" aria-label="Permalink to &quot;El historial del portapapeles no captura las copias&quot;">​</a></h2><p>Síntomas: las nuevas copias no aparecen en el panel de historial.</p><p>Lista de comprobación:</p><ol><li>Asegúrese de que la aplicación se está ejecutando y su icono de la barra de menú es visible.</li><li>Confirme que <strong>Supervisión del portapapeles</strong> está activada en <strong>Ajustes → Privacidad / General</strong>.</li><li>La aplicación necesita el permiso correspondiente de macOS para leer el portapapeles en segundo plano — consulte <a href="/es/guide/permissions.html">Permisos</a>.</li><li>Algunas aplicaciones (gestores de contraseñas, campos de entrada segura) bloquean intencionalmente el acceso al portapapeles; esto es esperado.</li></ol><h2 id="las-acciones-de-ia-en-la-nube-no-devuelven-un-resultado" tabindex="-1">Las acciones de IA en la nube no devuelven un resultado <a class="header-anchor" href="#las-acciones-de-ia-en-la-nube-no-devuelven-un-resultado" aria-label="Permalink to &quot;Las acciones de IA en la nube no devuelven un resultado&quot;">​</a></h2><p>Síntomas: una acción de IA falla, se queda colgada o muestra un error de configuración.</p><p>Lista de comprobación:</p><ol><li>Abra <strong>Ajustes → IA</strong> y confirme que hay un proveedor seleccionado y una clave introducida.</li><li>Verifique que la clave es válida para ese proveedor y tiene cuota/créditos.</li><li>Compruebe su conexión de red — la IA en la nube necesita acceso a internet.</li><li>Confirme que el nombre del modelo seleccionado es correcto para el proveedor.</li><li>Si el banner de configuración sigue apareciendo en la ventana de la Herramienta de IA, la clave no se ha guardado en el Keychain; vuelva a introducirla.</li></ol><h2 id="la-instalacion-desde-el-marketplace-no-anade-la-accion" tabindex="-1">La instalación desde el Marketplace no añade la acción <a class="header-anchor" href="#la-instalacion-desde-el-marketplace-no-anade-la-accion" aria-label="Permalink to &quot;La instalación desde el Marketplace no añade la acción&quot;">​</a></h2><p>Síntomas: al hacer clic en <strong>Instalar</strong> no pasa nada, o la aplicación no se abre.</p><p>Lista de comprobación:</p><ol><li>El enlace profundo <code>clipboardxai://install?action=&lt;id&gt;</code> debe ser gestionado por la aplicación instalada — asegúrese de que ClipboardxAI está instalado y en ejecución.</li><li>Si su navegador bloquea el enlace profundo, cópielo y ábralo manualmente, o instale desde la pestaña <strong>Marketplace</strong> de la propia aplicación.</li><li>Compruebe que el ID de la acción sigue publicado en el marketplace.</li></ol><h2 id="restablecer-la-aplicacion" tabindex="-1">Restablecer la aplicación <a class="header-anchor" href="#restablecer-la-aplicacion" aria-label="Permalink to &quot;Restablecer la aplicación&quot;">​</a></h2><p>Para restablecer los ajustes y borrar los datos locales:</p><ol><li>Salga de ClipboardxAI.</li><li>Elimine el contenedor (esto borra el historial y los ajustes):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><ol start="3"><li>Vuelva a abrir la aplicación y reconfigúrela. Las API keys del Keychain deben eliminarse por separado en <strong>Acceso a llaves</strong> si lo desea.</li></ol><h2 id="como-recopilar-registros-de-depuracion" tabindex="-1">Cómo recopilar registros de depuración <a class="header-anchor" href="#como-recopilar-registros-de-depuracion" aria-label="Permalink to &quot;Cómo recopilar registros de depuración&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copiar los registros al Escritorio para compartirlos</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard/Data/Library/Logs/Clipboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">AI/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>A continuación, abra un issue en <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub</a> y adjunte los registros.</p><h2 id="informar-de-un-problema" tabindex="-1">Informar de un problema <a class="header-anchor" href="#informar-de-un-problema" aria-label="Permalink to &quot;Informar de un problema&quot;">​</a></h2><p>Al abrir un issue, incluya:</p><ul><li>Versión de macOS (menú Apple → Acerca de este Mac)</li><li>Versión de ClipboardxAI (menú de la aplicación → Acerca de)</li><li>Pasos para reproducirlo</li><li>Registros (ver arriba)</li></ul><p>Esto ayuda a los mantenedores a identificar y corregir el problema más rápido.</p>`,28)])])}const b=e(o,[["render",r]]);export{h as __pageData,b as default};
